import React, { useEffect, useState } from 'react';
import { Animated, StyleProp, TextStyle } from 'react-native';
import { ColorPalette, useColors } from '../theme';

/**
 * Playful, rotating status text for a wait with no real progress to report (the meal-photo
 * analyze call runs ~10-15s server-side) - the same made-up-gerund style as Claude's own "thinking"
 * words ("noodling", "percolating"), themed to food/carb-counting. Hard-coded here on purpose -
 * the user asked explicitly for these to never be generated by a model, only picked from this
 * fixed front-end list. Reused wherever the app is waiting on the backend; pass `words` for a
 * different context.
 */
export const MEAL_ANALYSIS_LOADING_WORDS = [
  'Noodleizing…',
  'Carbulating…',
  'Portionizing…',
  'Plategazing…',
  'Sugarsleuthing…',
  'Caloribrating…',
  'Bitesizing…',
  'Forkulating…',
  'Chewculating…',
  'Snacktracking…',
  'Tastebudgeting…',
  'Carbcrunching…',
  'Macromancing…',
  'Grubgazing…',
  'Nibblenumbering…',
  'Crumbcounting…',
  'Veggiespotting…',
  'Sauceologizing…',
  'Yumifying…',
  'Contemplating your carbs…',
  'Ruminating on rice…',
  'Percolating the portions…',
] as const;

/** Picks a random item from `items`, never repeating `previous` back-to-back (unless it's the only option). */
function pickNext<T>(items: readonly T[], previous: T): T {
  if (items.length <= 1) return items[0];
  let next = previous;
  while (next === previous) {
    next = items[Math.floor(Math.random() * items.length)];
  }
  return next;
}

/** A few of the app's existing text-safe accent colours (see scripts/check-contrast.mjs), cycled
 * with the word for a "fun and friendly" feel instead of one flat muted tone. */
function funColors(colors: ColorPalette): string[] {
  return [colors.blue600, colors.purple600, colors.green600, colors.red600];
}

export function LoadingWords({
  words = MEAL_ANALYSIS_LOADING_WORDS,
  intervalMs = 1600,
  colorful = true,
  style,
}: {
  words?: readonly string[];
  intervalMs?: number;
  /** Cycle the text through a few fun accent colours instead of one flat muted tone. */
  colorful?: boolean;
  style?: StyleProp<TextStyle>;
}) {
  const colors = useColors();
  const palette = colorful ? funColors(colors) : [colors.ink2];
  const [word, setWord] = useState(() => words[Math.floor(Math.random() * words.length)] ?? '');
  const [color, setColor] = useState(() => palette[Math.floor(Math.random() * palette.length)]);
  // A lazy useState initializer (not useRef().current) for the same "create once, keep across
  // renders" need - the project's lint rules flag reading `.current` during render.
  const [opacity] = useState(() => new Animated.Value(1));

  useEffect(() => {
    const fadeMs = 220;
    const id = setInterval(() => {
      Animated.timing(opacity, { toValue: 0, duration: fadeMs, useNativeDriver: true }).start(() => {
        setWord((previous) => pickNext(words, previous));
        setColor((previous) => pickNext(palette, previous));
        Animated.timing(opacity, { toValue: 1, duration: fadeMs, useNativeDriver: true }).start();
      });
    }, intervalMs);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [words, intervalMs, colorful]);

  return (
    // Default colour assumes a normal theme surface; pass `style={{ color }}` to override on a
    // fixed-colour background (e.g. a dark scrim) that doesn't follow the theme.
    <Animated.Text style={[{ opacity, fontFamily: 'Manrope_700Bold', fontSize: 13, color }, style]}>{word}</Animated.Text>
  );
}
